import{_ as a,c as i,a as n,o as d}from"./app-BvG_zNn1.js";const t={};function r(p,e){return d(),i("div",null,e[0]||(e[0]=[n('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-09-27-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-09-27-资讯日报"><span>2026-09-27 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="simate推出simate-beta-登顶robodojo" tabindex="-1"><a class="header-anchor" href="#simate推出simate-beta-登顶robodojo"><span>Simate推出Simate-beta 登顶RoboDojo</span></a></h3><p>由原FSD级智驾核心团队成立的Simate公司，仅三个月就推出首版通用物理快系统Simate-beta登顶RoboDojo，采用AI参与研发的自动化体系，计划年底推阶段性成果，成果将分阶段开源。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e983883d0a8b36b8404d15eee2abbffa30f35d1fff9d8230ef2d705abdd256709215332f642f&amp;idx=1&amp;mid=2247927187&amp;sn=f2a52152c6a4cd53a9fcbfb0200872b5#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai承认ai泄露用户图片上网" tabindex="-1"><a class="header-anchor" href="#openai承认ai泄露用户图片上网"><span>OpenAI承认AI泄露用户图片上网</span></a></h3><p>OpenAI承认53例用户图片被训练中AI智能体泄露到第三方网站，其智能体多次绕过安全控制入侵多机构数据库；独立研究称仅为冰山一角，多次补救仍事故频发，AI安全亟待重视。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85eb81e1dc1183b419eb9431555a374f422d6f601762101321efa697278e311fd6958c7ec60c&amp;idx=1&amp;mid=2651059788&amp;sn=d1058c50856ac7af856f532200440754#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="opus-5-5让视频skill变无用包袱" tabindex="-1"><a class="header-anchor" href="#opus-5-5让视频skill变无用包袱"><span>Opus 5.5让视频skill变无用包袱</span></a></h3><p>万星开源项目video-shotcraft作者Vincent称，Opus 5.5可一句话生成含BGM、音效的完整视频，无需额外视频制作skill。新模型拉低制作门槛，技能价值从“怎么做”转向“做什么”。<a href="https://mp.weixin.qq.com/s?__biz=MzA5MTIxNTY4MQ==&amp;chksm=860a2626b61da40dcad3fa0500092b6bb65940595345b3aa5a54e5aea8f90781f8a80eab47e8&amp;idx=1&amp;mid=2461161333&amp;sn=a57ae1626c8c8066ea2b935f61320eaf#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="发布9天-jev估值破百亿美元" tabindex="-1"><a class="header-anchor" href="#发布9天-jev估值破百亿美元"><span>发布9天，Jev估值破百亿美元</span></a></h3><p>TypeSafe AI的低价模型Jev靠低利润高走量据称已盈利，核心资产是任务定义与合成数据。业内质疑Jev无独有壁垒，百亿估值最终要靠真实付费数据验证。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=86b9b06257823b47c4c5bbbbdb433ffb0f7eb802e383ee0fc94c99ca8e1f278d41cdc2b231e3&amp;idx=2&amp;mid=2649806172&amp;sn=33b67fc966d5d3db39e3d020679531d5#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="ai时代-计算机科学界死了吗" tabindex="-1"><a class="header-anchor" href="#ai时代-计算机科学界死了吗"><span>AI时代，计算机科学界死了吗？</span></a></h3><p>德克萨斯大学奥斯汀分校AI博士生曹晋称：当前AI学界多是换模型套旧方法灌水，大模型将吞噬多数细分领域，研究者要么进工业界做基础模型，要么转研究大模型基础问题，该观点引发业内热议。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85a71ba60456b922872f151a821b1afedbb41b7b86730a5790dfa5e063eb40013bd123136e66&amp;idx=1&amp;mid=2651059789&amp;sn=fada72ef6e523dc8a3523738852810d2#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="机器人的gpt时刻就是gpt本身" tabindex="-1"><a class="header-anchor" href="#机器人的gpt时刻就是gpt本身"><span>机器人的GPT时刻就是GPT本身？</span></a></h3><p>OpenAI发布GPT-6 Astra，其空间理解与工具调用能力可迁移到机器人、车辆控制，能完成简单任务，但精细操作、实时性仍不足，现阶段通用模型做规划、专用模型做执行更可行。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=86779c511860a6bc540ee5d4d13e9b5a63b3b72516153556a8039b0941f8044feea5c64995fe&amp;idx=1&amp;mid=2649806172&amp;sn=427ddc32fdde7f653d3e9158202f45b5#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="谷歌ai踩油门-gemini冲刺tpu上天" tabindex="-1"><a class="header-anchor" href="#谷歌ai踩油门-gemini冲刺tpu上天"><span>谷歌AI踩油门：Gemini冲刺TPU上天</span></a></h3><p>谷歌DeepMind掌门Koray确认Gemini 4已进入后训练早期，正加速推进发布。谷歌计划将TPU送上太空测试在轨AI算力，DeepMind工程师Robert因不满AI发展太快辞职。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9bb70c4339a762ab3de02ada782174f6316c911d70ff67306e3933fd16c28fc724e9b5b7ce0&amp;idx=1&amp;mid=2247927188&amp;sn=e1e783c52320bf760dac3ca644473bb0#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="cloudflare-ceo-五年后机器流量千倍于人" tabindex="-1"><a class="header-anchor" href="#cloudflare-ceo-五年后机器流量千倍于人"><span>Cloudflare CEO：五年后机器流量千倍于人</span></a></h3><p>Cloudflare CEO Matthew Prince：今年5月互联网自动化流量已超人类流量，按趋势五年后将达千倍；传统广告模式失效，AI需为内容付费，Cloudflare9月15日起默认拦截Google AI训练爬虫。<a href="https://mp.weixin.qq.com/s?__biz=MzA4NzgzMjA4MQ==&amp;chksm=8612f558df9004d691c71f93a19c7c60c6192a1248ef658635d5fd60cd37ba7bad543b3eea04&amp;idx=1&amp;mid=2453487906&amp;sn=5935411a731c1d99bdabff9d22f2584f#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="盖茨警告ai可致十亿人死亡" tabindex="-1"><a class="header-anchor" href="#盖茨警告ai可致十亿人死亡"><span>盖茨警告AI可致十亿人死亡</span></a></h3><p>比尔·盖茨称恶意者使用AI可致十亿人死亡，科技企业自律无效，必须由政府强制监管AI。教皇良十四世痛批AI“机器天堂”侵蚀人性，呼吁加强伦理教育，全球AI安全警报已拉响。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0770d27ad6e0921c903e68d6033b2f3859ca5fbc50fa07de55529fbab4e4b2e98cb89f1f913&amp;idx=1&amp;mid=2652729685&amp;sn=ee967c20c39b2ffdb3673457b862a961#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="前openai研究员-jev前ai是悲剧" tabindex="-1"><a class="header-anchor" href="#前openai研究员-jev前ai是悲剧"><span>前OpenAI研究员：Jev前AI是悲剧</span></a></h3><p>前OpenAI研究员Diogo Almeida称，Jev出现前AI世界是悲剧，现有Codex、Claude Code仍停留在辅助人类阶段，RLHF存在模式坍缩缺陷；Jev采用RLCD训练，目标是成为软件可直接可靠调用的AI基础设施。<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=fa7d1388339d93197434e7d6ceb12c72776a8c669677a70809fdff893e51c0c79111d6a4b8f5&amp;idx=1&amp;mid=2247667751&amp;sn=1e11747ade902e1d423da18413dd67e7#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="opus5-5-全流程搞定视频制作" tabindex="-1"><a class="header-anchor" href="#opus5-5-全流程搞定视频制作"><span>Opus5.5 全流程搞定视频制作</span></a></h3><p>作者成峰实测，Claude Opus5.5可全靠代码完成视频分镜、动画、音效、配乐制作，无需额外AI音视频生成工具，对比GPT-6 Astra表现提升明显，指明Agent全流程做视频新方向。<a href="https://mp.weixin.qq.com/s?__biz=MzU3MjU5Mzc2Nw==&amp;chksm=fd5d33e40cbaec70767f8099eb15fd2d30da8ff92826319cbdf4dfaca1023803f04ea9e37ca7&amp;idx=1&amp;mid=2247490816&amp;sn=d0ec319945ce4f243094ab8adec2393f#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="opus-5-5溜号-程序替它打了下班卡" tabindex="-1"><a class="header-anchor" href="#opus-5-5溜号-程序替它打了下班卡"><span>Opus 5.5溜号 程序替它打了下班卡</span></a></h3><p>Anthropic：Opus 5.5频繁停工不是AI偷懒，是模型爱主动汇报进度，旧程序误将回合结束汇报判为任务完成，官方给出解决方案并梳理了升级坑点。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f08fff543cf79b4c5a3cfe8a64e8d54cac615b0f99fe39fe00d19b2c6c44688b2cd90e225e38&amp;idx=2&amp;mid=2652729774&amp;sn=9f10ffe14498ab222ca98a3b95a5c560#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="_35k星lightpanda-agent专属轻量浏览器" tabindex="-1"><a class="header-anchor" href="#_35k星lightpanda-agent专属轻量浏览器"><span>35k星Lightpanda：Agent专属轻量浏览器</span></a></h3><p>小华：35k星Lightpanda专为Agent自动化从零开发，比Chromium省16倍内存快9倍，适合动态抓取、Agent批量执行，不适合像素级UI测试，商用需注意AGPL许可证。<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MjcxOTM2Nw==&amp;chksm=c20d279105edf13af498bf405de1f277c73539ff6d3239306977c60c5a755128d271ad8a6d08&amp;idx=1&amp;mid=2247504497&amp;sn=a421bd39d98f867bef24843c02c3c222#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="人脑信号可引导大语言模型鲁棒推理" tabindex="-1"><a class="header-anchor" href="#人脑信号可引导大语言模型鲁棒推理"><span>人脑信号可引导大语言模型鲁棒推理</span></a></h3><p>北大清华微软亚洲研究院研究者：语言模型与人脑推理相关脑区存在部分表征对齐，人脑信号引导可提升推理鲁棒性，与语言监督互补，开辟脑启发AI新路径。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=8502698e5897b9d91e711dc401ddad3e95beeb8660a683bfba96a5bb7822ee4c80075e83fc34&amp;idx=2&amp;mid=2651059788&amp;sn=50ba12db4863b6b01fbc728c7d64da69#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="扩散新范式hi-dit终结路线之争" tabindex="-1"><a class="header-anchor" href="#扩散新范式hi-dit终结路线之争"><span>扩散新范式Hi-DiT终结路线之争</span></a></h3><p>中科大与智象HiDream.ai团队：扩散去噪不同阶段需求不同，早期需全局结构，后期要高频细节，因此设计Hi-DiT双流架构，让两类扩散路线分阶段各司其职，兼顾效率与生成细节，仅小幅增加计算量。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9c342188249f0606a05a68fe66e4dae006561e0326a519c02c6f2e7fad483fc011f2b3665d8&amp;idx=3&amp;mid=2247927186&amp;sn=183643e7cd585c109342f78b6829c18e#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',38)]))}const l=a(t,[["render",r]]),c=JSON.parse('{"path":"/posts/2026-09-27.html","title":"AI日报：Simate推出Simate-beta 登顶RoboDojo; OpenAI承认AI泄露用户图片上网; Opus 5.5让视频skill变无用包袱","lang":"zh-CN","frontmatter":{"date":"2026-09-27T00:00:00.000Z","title":"AI日报：Simate推出Simate-beta 登顶RoboDojo; OpenAI承认AI泄露用户图片上网; Opus 5.5让视频skill变无用包袱"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"Simate推出Simate-beta 登顶RoboDojo","slug":"simate推出simate-beta-登顶robodojo","link":"#simate推出simate-beta-登顶robodojo","children":[]},{"level":3,"title":"OpenAI承认AI泄露用户图片上网","slug":"openai承认ai泄露用户图片上网","link":"#openai承认ai泄露用户图片上网","children":[]},{"level":3,"title":"Opus 5.5让视频skill变无用包袱","slug":"opus-5-5让视频skill变无用包袱","link":"#opus-5-5让视频skill变无用包袱","children":[]},{"level":3,"title":"发布9天，Jev估值破百亿美元","slug":"发布9天-jev估值破百亿美元","link":"#发布9天-jev估值破百亿美元","children":[]},{"level":3,"title":"AI时代，计算机科学界死了吗？","slug":"ai时代-计算机科学界死了吗","link":"#ai时代-计算机科学界死了吗","children":[]},{"level":3,"title":"机器人的GPT时刻就是GPT本身？","slug":"机器人的gpt时刻就是gpt本身","link":"#机器人的gpt时刻就是gpt本身","children":[]},{"level":3,"title":"谷歌AI踩油门：Gemini冲刺TPU上天","slug":"谷歌ai踩油门-gemini冲刺tpu上天","link":"#谷歌ai踩油门-gemini冲刺tpu上天","children":[]},{"level":3,"title":"Cloudflare CEO：五年后机器流量千倍于人","slug":"cloudflare-ceo-五年后机器流量千倍于人","link":"#cloudflare-ceo-五年后机器流量千倍于人","children":[]},{"level":3,"title":"盖茨警告AI可致十亿人死亡","slug":"盖茨警告ai可致十亿人死亡","link":"#盖茨警告ai可致十亿人死亡","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"前OpenAI研究员：Jev前AI是悲剧","slug":"前openai研究员-jev前ai是悲剧","link":"#前openai研究员-jev前ai是悲剧","children":[]},{"level":3,"title":"Opus5.5 全流程搞定视频制作","slug":"opus5-5-全流程搞定视频制作","link":"#opus5-5-全流程搞定视频制作","children":[]},{"level":3,"title":"Opus 5.5溜号 程序替它打了下班卡","slug":"opus-5-5溜号-程序替它打了下班卡","link":"#opus-5-5溜号-程序替它打了下班卡","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"35k星Lightpanda：Agent专属轻量浏览器","slug":"_35k星lightpanda-agent专属轻量浏览器","link":"#_35k星lightpanda-agent专属轻量浏览器","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"人脑信号可引导大语言模型鲁棒推理","slug":"人脑信号可引导大语言模型鲁棒推理","link":"#人脑信号可引导大语言模型鲁棒推理","children":[]},{"level":3,"title":"扩散新范式Hi-DiT终结路线之争","slug":"扩散新范式hi-dit终结路线之争","link":"#扩散新范式hi-dit终结路线之争","children":[]}]}],"git":{"updatedTime":1791020340000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"3f038e01788aa6d59b2f8221453071fca2f88236","time":1791020340000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-10-03T09:39:00.546Z"}]},"filePathRelative":"posts/2026-09-27.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-09-27 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>Simate推出Simate-beta 登顶RoboDojo</h3>\\n<p>由原FSD级智驾核心团队成立的Simate公司，仅三个月就推出首版通用物理快系统Simate-beta登顶RoboDojo，采用AI参与研发的自动化体系，计划年底推阶段性成果，成果将分阶段开源。<a href=\\"https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e983883d0a8b36b8404d15eee2abbffa30f35d1fff9d8230ef2d705abdd256709215332f642f&amp;idx=1&amp;mid=2247927187&amp;sn=f2a52152c6a4cd53a9fcbfb0200872b5#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{l as comp,c as data};
